"""Symbols of a decomp build (address, size, type), generated by tools/gen_symbols.py."""

from dataclasses import dataclass
from functools import cache
from importlib.resources import files

FIRERED_SWITCH = "firered_switch"


@dataclass(frozen=True)
class Symbol:
    name: str
    address: int
    size: int
    kind: str

    @property
    def is_thumb_code(self) -> bool:
        return self.kind in "Tt" and self.address >= 0x08000000

    @property
    def call_address(self) -> int:
        """THUMB functions are called with bit 0 set."""
        return self.address | 1 if self.is_thumb_code else self.address


@cache
def table(build: str = FIRERED_SWITCH) -> dict[str, Symbol]:
    text = files("swg3").joinpath("data", f"{build}.sym").read_text(encoding="utf-8")
    symbols = {}
    for line in text.splitlines():
        address, size, kind, name = line.split("\t")
        symbols.setdefault(name, Symbol(name, int(address, 16), int(size, 16), kind))
    return symbols


def lookup(name: str, build: str = FIRERED_SWITCH) -> Symbol:
    try:
        return table(build)[name]
    except KeyError:
        raise KeyError(f"symbol {name!r} not found in {build}") from None
